def colon_tuplex(tuplex, m, n):
    """Write a function to get a colon of a tuple."""
    items = list(tuplex)
    current = items[m]
    if not isinstance(current, list):
        raise TypeError("element at index m must be a list")
    items[m] = current + [n]
    return tuple(items)
